INSERT INTO zinas (virsraksts, teksts, kategorija, izveidots, publicets) VALUES
('4. diena — rīta pastaiga, Limbaži un pirts',
'Ceturtā diena sākās ar rīta pastaigu pludmalē kopā ar suņiem. Rīta saule spīdēja, pūta viegls vējš — tāds rāms, gaišs dienas sākums.\n\nPēc pludmales pirmā pietura, protams, pēc rīta kafijas — īru kapučīno, lai diena ieskrietos. Tad ceļš uz Limbažiem: apciemojām Limbažu "Tīni" un pāris citus veikalus. Pa ceļam arī mašīnas mazgāšana "Puto" pašapkalpošanās mazgātavā — arī tāda ikdienas lieta ceļojuma vidū.\n\nPēcpusdienā vēlreiz atpakaļ uz jūru, un pēc tam uz mājiņu — pirtī. Silts tvaiks pēc vēsās jūras dienas; labāku dienas noslēgumu grūti iedomāties.\n\n⸻\n\nNeljäs päivä alkoi aamukävelyllä rannalla koirien kanssa. Aamuaurinko paistoi, kevyt tuuli puhalsi — rauhallinen, kirkas alku päivälle.\n\nRannan jälkeen ensimmäinen pysähdys oli tietenkin aamukahville — irlantilainen cappuccino, jotta päivä lähti käyntiin. Sitten tie vei Limbažiin: vierailimme Limbažu Tīnessä ja parissa muussa kaupassa. Matkalla myös auton pesu Puton itsepalvelupesulassa — sellaisiakin arjen juttuja matkan keskellä.\n\nIltapäivällä vielä kerran takaisin merelle, ja sen jälkeen mökille — saunaan. Lämmin löyly viileän merenpäivän jälkeen; parempaa päivän päätöstä on vaikea kuvitella.',
'celojums',
'2026-10-20 19:00:00',
1);
